package config

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

type Config struct {
	BaseURL     string
	APIKey      string
	Model       string
	ProModel    string
	OllamaURL   string
	OllamaModel string
	Provider    string // 上次使用的提供商: deepseek / ollama
	MaxTurns    int
}

func Load() Config {
	homeDir, _ := os.UserHomeDir()
	globalEnv := filepath.Join(homeDir, ".gowhale", ".env")

	loadDotEnv(globalEnv)
	loadDotEnv(".env")

	cfg := Config{
		BaseURL:     getenv("AICODE_BASE_URL", "https://api.deepseek.com/v1"),
		APIKey:      getenv("AICODE_API_KEY", ""),
		Model:       getenv("AICODE_MODEL", "deepseek-v4-flash"),
		ProModel:    getenv("AICODE_PRO_MODEL", "deepseek-v4-pro"),
		OllamaURL:   getenv("AICODE_OLLAMA_URL", ""),
		OllamaModel: getenv("AICODE_OLLAMA_MODEL", ""),
		Provider:    getenv("AICODE_PROVIDER", "deepseek"),
		MaxTurns:    getenvInt("AICODE_MAX_TURNS", 40),
	}

	// 自动恢复上次使用的提供商
	if cfg.Provider == "ollama" && cfg.OllamaURL != "" && cfg.OllamaModel != "" {
		cfg.BaseURL = cfg.OllamaURL
		cfg.APIKey = "ollama"
		cfg.Model = cfg.OllamaModel
		cfg.ProModel = cfg.OllamaModel
	}

	if cfg.APIKey == "" {
		cfg.APIKey = promptKey(globalEnv)
	}

	return cfg
}

// PromptOllama 首次使用 Ollama 时交互式询问，保存到 ~/.gowhale/.env。
func PromptOllama(in *bufio.Reader) (url, model string) {
	homeDir, _ := os.UserHomeDir()
	savePath := filepath.Join(homeDir, ".gowhale", ".env")

	fmt.Print("\n首次使用 Ollama，需要配置：\n")
	fmt.Print("  Ollama 地址 [默认 http://localhost:11434/v1]: ")
	input, _ := in.ReadString('\n')
	url = strings.TrimSpace(input)
	if url == "" {
		url = "http://localhost:11434/v1"
	}

	fmt.Print("  模型名（如 qwen3-coder:30b，用 ollama list 查看）: ")
	input, _ = in.ReadString('\n')
	model = strings.TrimSpace(input)
	if model == "" {
		fmt.Println("  ✗ 模型名不能为空")
		return "", ""
	}

	// 保存到 ~/.gowhale/.env
	dir := filepath.Dir(savePath)
	os.MkdirAll(dir, 0o700)

	// 读取已有配置
	existing, _ := os.ReadFile(savePath)
	content := string(existing)
	if !strings.Contains(content, "AICODE_OLLAMA_URL") {
		content += fmt.Sprintf("\n# Ollama 本地模型\nAICODE_OLLAMA_URL=%s\nAICODE_OLLAMA_MODEL=%s\n", url, model)
		os.WriteFile(savePath, []byte(content), 0o600)
		fmt.Printf("  ✓ 已保存到 %s\n", savePath)
	}

	os.Setenv("AICODE_OLLAMA_URL", url)
	os.Setenv("AICODE_OLLAMA_MODEL", model)
	return
}

// SaveProvider 保存当前使用的提供商到 ~/.gowhale/.env。
func SaveProvider(provider string) {
	homeDir, _ := os.UserHomeDir()
	savePath := filepath.Join(homeDir, ".gowhale", ".env")

	existing, _ := os.ReadFile(savePath)
	content := string(existing)

	// 移除旧的 AICODE_PROVIDER 行
	lines := strings.Split(content, "\n")
	var newLines []string
	for _, line := range lines {
		if !strings.HasPrefix(strings.TrimSpace(line), "AICODE_PROVIDER") {
			newLines = append(newLines, line)
		}
	}
	content = strings.Join(newLines, "\n")

	// 追加新的
	content = strings.TrimRight(content, "\n") + fmt.Sprintf("\nAICODE_PROVIDER=%s\n", provider)
	os.WriteFile(savePath, []byte(content), 0o600)
	os.Setenv("AICODE_PROVIDER", provider)
}

func getenv(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

func getenvInt(key string, def int) int {
	if v := os.Getenv(key); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 {
			return n
		}
	}
	return def
}

func loadDotEnv(path string) {
	data, err := os.ReadFile(path)
	if err != nil {
		return
	}
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		kv := strings.SplitN(line, "=", 2)
		if len(kv) != 2 {
			continue
		}
		key := strings.TrimSpace(kv[0])
		val := strings.TrimSpace(kv[1])
		val = strings.Trim(val, "\"'")
		if key != "" && os.Getenv(key) == "" {
			os.Setenv(key, val)
		}
	}
}

func promptKey(savePath string) string {
	fmt.Fprintln(os.Stderr, "未检测到 API Key。")
	fmt.Fprint(os.Stderr, "请输入 DeepSeek API Key（如 sk-xxx）：")

	reader := bufio.NewReader(os.Stdin)
	input, err := reader.ReadString('\n')
	if err != nil {
		fmt.Fprintln(os.Stderr, "读取失败，请设置环境变量 AICODE_API_KEY 后重试。")
		os.Exit(1)
	}
	key := strings.TrimSpace(input)
	if key == "" {
		fmt.Fprintln(os.Stderr, "Key 不能为空，请设置环境变量 AICODE_API_KEY 后重试。")
		os.Exit(1)
	}

	dir := filepath.Dir(savePath)
	if err := os.MkdirAll(dir, 0o700); err == nil {
		content := fmt.Sprintf("# GoWhale 配置文件\nAICODE_API_KEY=%s\n", key)
		if err := os.WriteFile(savePath, []byte(content), 0o600); err == nil {
			fmt.Fprintf(os.Stderr, "✓ 已保存到 %s，下次无需重复输入。\n", savePath)
		}
	}

	os.Setenv("AICODE_API_KEY", key)
	return key
}

package llm

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"

	"gowhale/internal/config"
)

type Message struct {
	Role       string     `json:"role"`
	Content    string     `json:"content"`
	ToolCalls  []ToolCall `json:"tool_calls,omitempty"`
	ToolCallID string     `json:"tool_call_id,omitempty"`
}

type ToolCall struct {
	ID       string       `json:"id"`
	Type     string       `json:"type"`
	Function FunctionCall `json:"function"`
}

type FunctionCall struct {
	Name      string `json:"name"`
	Arguments string `json:"arguments"`
}

type Tool struct {
	Type     string             `json:"type"`
	Function ToolFunctionSchema `json:"function"`
}

type ToolFunctionSchema struct {
	Name        string         `json:"name"`
	Description string         `json:"description"`
	Parameters  map[string]any `json:"parameters"`
}

type Usage struct {
	PromptTokens     int `json:"prompt_tokens"`
	CompletionTokens int `json:"completion_tokens"`
	TotalTokens      int `json:"total_tokens"`
}

type Client struct {
	cfg  config.Config
	http *http.Client
}

func NewClient(cfg config.Config) *Client {
	return &Client{cfg: cfg, http: &http.Client{Timeout: 5 * time.Minute}}
}

func (c *Client) Model() string    { return c.cfg.Model }
func (c *Client) BaseURL() string  { return c.cfg.BaseURL }
func (c *Client) SetModel(m string)  { c.cfg.Model = m }
func (c *Client) SetBaseURL(u string) { c.cfg.BaseURL = u }
func (c *Client) SetAPIKey(k string)  { c.cfg.APIKey = k }

// SwitchTo 一键切换提供商
func (c *Client) SwitchTo(baseURL, apiKey, model, proModel string) {
	c.cfg.BaseURL = baseURL
	c.cfg.APIKey = apiKey
	c.cfg.Model = model
	c.cfg.ProModel = proModel
}

type chatRequest struct {
	Model     string    `json:"model"`
	Messages  []Message `json:"messages"`
	Tools     []Tool    `json:"tools,omitempty"`
	MaxTokens int       `json:"max_tokens,omitempty"`
}

type chatResponse struct {
	Choices []struct {
		Message Message `json:"message"`
	} `json:"choices"`
	Usage *Usage `json:"usage,omitempty"`
}

func (c *Client) Chat(messages []Message, tools []Tool) (Message, Usage, error) {
	body, err := json.Marshal(chatRequest{
		Model:     c.cfg.Model,
		Messages:  messages,
		Tools:     tools,
		MaxTokens: 8192,
	})
	if err != nil {
		return Message{}, Usage{}, err
	}

	url := strings.TrimRight(c.cfg.BaseURL, "/") + "/chat/completions"
	req, err := http.NewRequest(http.MethodPost, url, bytes.NewReader(body))
	if err != nil {
		return Message{}, Usage{}, err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", "Bearer "+c.cfg.APIKey)

	resp, err := c.http.Do(req)
	if err != nil {
		return Message{}, Usage{}, err
	}
	defer resp.Body.Close()

	raw, readErr := io.ReadAll(resp.Body)
	if resp.StatusCode != http.StatusOK {
		detail := strings.TrimSpace(string(raw))
		if readErr != nil {
			detail = fmt.Sprintf("(读取错误体失败: %v)", readErr)
		}
		return Message{}, Usage{}, fmt.Errorf("大模型返回错误 %d: %s", resp.StatusCode, detail)
	}

	var parsed chatResponse
	if err := json.Unmarshal(raw, &parsed); err != nil {
		return Message{}, Usage{}, fmt.Errorf("解析响应失败: %w", err)
	}
	if len(parsed.Choices) == 0 {
		return Message{}, Usage{}, fmt.Errorf("模型未返回任何内容")
	}
	var usage Usage
	if parsed.Usage != nil {
		usage = *parsed.Usage
	}
	return parsed.Choices[0].Message, usage, nil
}

func FormatTokens(n int) string {
	if n < 1000 {
		return fmt.Sprintf("%d", n)
	}
	return fmt.Sprintf("%.1fk", float64(n)/1000)
}

package tools

import (
	"encoding/json"

	"gowhale/internal/llm"
)

// Tool 是一个「技能」：模型可以调用它来操作本地环境。
type Tool interface {
	Name() string
	Description() string
	// Schema 返回参数的 JSON Schema（OpenAI function parameters 格式）。
	Schema() map[string]any
	// Execute 执行工具，args 是模型给出的参数（JSON）。
	Execute(args json.RawMessage) (string, error)
}

// Approvable 由「有副作用、需要用户审批」的工具实现。
// 未实现该接口的工具（如只读的 read_file / list_dir）会被自动放行。
type Approvable interface {
	// Review 检查本次调用，返回审批决策。
	Review(args json.RawMessage) Decision
}

// Decision 描述一次操作的审批需求与「授权作用域」。
// 用户一旦对某个作用域选择「始终允许」，同作用域的后续操作将自动放行。
type Decision struct {
	NeedApproval bool   // 是否需要审批
	Danger       string // 高危原因（非空表示危险；危险操作不支持「始终允许」）
	ScopeKind    string // 作用域类型："dir"（按目录，前缀匹配）| "session"（会话级）| ""（不记忆）
	Scope        string // 作用域标识（dir：目录路径；session：命名键）
}

// Registry 管理所有可用工具。
type Registry struct {
	tools map[string]Tool
}

// New 用给定的工具集合创建注册表。
func New(ts ...Tool) *Registry {
	m := make(map[string]Tool, len(ts))
	for _, t := range ts {
		m[t.Name()] = t
	}
	return &Registry{tools: m}
}

// Definitions 把所有工具转换成发给模型的定义列表。
func (r *Registry) Definitions() []llm.Tool {
	defs := make([]llm.Tool, 0, len(r.tools))
	for _, t := range r.tools {
		defs = append(defs, llm.Tool{
			Type: "function",
			Function: llm.ToolFunctionSchema{
				Name:        t.Name(),
				Description: t.Description(),
				Parameters:  t.Schema(),
			},
		})
	}
	return defs
}

// Lookup 按名称取出工具。
func (r *Registry) Lookup(name string) (Tool, bool) {
	t, ok := r.tools[name]
	return t, ok
}

package tools

import (
	"encoding/json"
	"errors"
	"fmt"
	"os/exec"
	"runtime"
	"strings"
	"time"
	"unicode/utf8"

	"golang.org/x/text/encoding/simplifiedchinese"
)

// maxOutput 限制返回给模型的输出长度，避免刷屏和撑爆上下文。
const maxOutput = 4000

// ShellTool 执行 shell 命令。是否放行由审批门决定（见 Review）。
type ShellTool struct{}

func (ShellTool) Name() string { return "execute_shell" }

func (ShellTool) Description() string {
	return "执行 shell 命令。Linux/macOS 用 sh，Windows 用 cmd。执行前需审批。长期服务设 background=true。"
}

// Review 让 execute_shell 走审批门：始终需要确认，并对危险命令给出警告原因。
// 作用域为会话级——用户「始终允许」后，本次会话内的非危险命令自动放行。
func (ShellTool) Review(args json.RawMessage) Decision {
	var p struct {
		Command string `json:"command"`
	}
	_ = json.Unmarshal(args, &p)
	return Decision{
		NeedApproval: true,
		Danger:       CheckDanger(p.Command),
		ScopeKind:    "session",
		Scope:        "shell",
	}
}

func (ShellTool) Schema() map[string]any {
	return map[string]any{
		"type": "object",
		"properties": map[string]any{
			"command": map[string]any{
				"type":        "string",
				"description": "要执行的命令。根据上方运行环境中的操作系统和 shell 类型，使用对应的命令语法。" +
					"Windows cmd 语法：dir, type, findstr, del, move, copy, echo %VAR%。" +
					"Linux sh 语法：ls, cat, grep, rm, mv, cp, echo $VAR。" +
					"长期服务用 background=true。",
			},
			"background": map[string]any{
				"type":        "boolean",
				"description": "设为 true 时命令在后台运行，立即返回（用于启动长期运行的服务如 Web 服务器）。默认 false。",
			},
		},
		"required": []string{"command"},
	}
}

func (ShellTool) Execute(args json.RawMessage) (string, error) {
	var p struct {
		Command    string `json:"command"`
		Background bool   `json:"background"`
	}
	if err := json.Unmarshal(args, &p); err != nil {
		return "", fmt.Errorf("参数解析失败: %w", err)
	}
	if strings.TrimSpace(p.Command) == "" {
		return "", errors.New("command 不能为空")
	}
	if err := CheckShell(p.Command); err != nil {
		return "", err
	}

	// 后台模式：启动不等待，立即返回 PID（用于服务）
	if p.Background {
		return runBackground(p.Command), nil
	}

	// 统一用 sh -c 执行（Windows 下用 cmd /c）。
	name, flag := "sh", "-c"
	if runtime.GOOS == "windows" {
		name, flag = "cmd", "/c"
	}

	ctxCmd := exec.Command(name, flag, p.Command)
	done := make(chan struct{})
	var out []byte
	var runErr error
	go func() {
		out, runErr = ctxCmd.CombinedOutput()
		close(done)
	}()

	// 等待命令完成或超时（60 秒）。
	// 进度反馈由 Agent 层的 spinner 统一管理，这里只做控制。
	timeout := time.After(60 * time.Second)
	select {
	case <-done:
		// 正常完成
	case <-timeout:
		_ = ctxCmd.Process.Kill()
		return "", fmt.Errorf("命令执行超时（60 秒）。→ 不要重试同样的命令。如果是长期服务请用 background=true；如果是命令卡住请换替代方案")
	}

	result := strings.TrimSpace(decodeOutput(out))
	if len(result) > maxOutput {
		result = result[:maxOutput] + "\n...(输出过长已截断)"
	}
	if runErr != nil {
		if result == "" {
			return "", fmt.Errorf("命令执行失败: %w。→ 不要重试此命令。请检查命令拼写、依赖是否安装、路径是否正确，然后换一种不同的方式", runErr)
		}
		return fmt.Sprintf("命令返回非零退出码（%v）。输出：\n%s\n→ 不要重试此命令。请根据上面的错误输出，换一种完全不同的方式解决问题", runErr, result), nil
	}
	if result == "" {
		result = "(命令执行成功，无输出)"
	}
	return result, nil
}

// runBackground 在后台启动命令，立即返回，不等待完成。
// 确保从工作区目录启动，这样 mvn/npm 等命令能找到配置文件。
func runBackground(cmdStr string) string {
	if runtime.GOOS == "windows" {
		c := exec.Command("cmd", "/c", "start", "/B", "cmd", "/c", cmdStr)
		c.Dir = workspace // 确保从工作区启动
		if err := c.Start(); err != nil {
			return fmt.Sprintf("后台启动失败: %v", err)
		}
		return fmt.Sprintf("命令已在后台启动。用 netstat/curl 验证服务是否就绪。\n命令: %s", cmdStr)
	}
	c := exec.Command("sh", "-c", cmdStr+" &")
	c.Dir = workspace
	if err := c.Start(); err != nil {
		return fmt.Sprintf("后台启动失败: %v", err)
	}
	return fmt.Sprintf("命令已在后台启动（PID %d）。用 curl/netstat 验证服务是否就绪。\n命令: %s", c.Process.Pid, cmdStr)
}

// decodeOutput 把子进程输出转成 UTF-8。
// Windows 中文控制台（javac、cmd 等）输出多为 GBK/GB18030 编码，
// 直接当 UTF-8 会乱码。策略：已是合法 UTF-8 就原样返回；否则按 GB18030 解码。
func decodeOutput(b []byte) string {
	if len(b) == 0 || utf8.Valid(b) {
		return string(b)
	}
	if dec, err := simplifiedchinese.GB18030.NewDecoder().Bytes(b); err == nil && utf8.Valid(dec) {
		return string(dec)
	}
	return string(b) // 兜底：无法识别则原样返回
}

package agent

import (
	"fmt"
	"path/filepath"
	"strings"
)

// Approver 负责在有副作用的操作执行前，向用户征求确认（审批门）。
// 支持「始终允许」：按作用域（目录/会话）记住授权，之后同作用域操作自动放行。
// 不直接读 stdin —— 由外部调用方（终端 goroutine 或 TUI）通过 SendDecision 注入决策。
type Approver struct {
	decisions    chan ApprovalReply // 外部注入决策
	approvedDirs []string           // 已授权的目录（前缀匹配，含子目录）
	approvedSess map[string]bool    // 已授权的会话级作用域（如 shell）
}

// NewApprover 创建审批器。
func NewApprover() *Approver {
	return &Approver{
		decisions:    make(chan ApprovalReply, 1),
		approvedSess: map[string]bool{},
	}
}

// SendDecision 外部向审批器发送一个决策。非阻塞（buffer=1）。
func (a *Approver) SendDecision(reply ApprovalReply) {
	select {
	case a.decisions <- reply:
	default:
	}
}

// Ask 根据审批决策决定是否放行。
// 如果已通过「始终允许」记忆放行，直接返回 true 不等待。
// 否则阻塞等待外部通过 SendDecision 注入决策。
func (a *Approver) Ask(name string, warning string, scopeKind string, scope string) bool {
	// 检查记忆
	if warning == "" && a.isApproved(scopeKind, scope) {
		return true
	}

	// 阻塞等待外部决策
	reply := <-a.decisions
	if reply.Permanent && warning == "" {
		a.remember(scopeKind, scope)
	}
	return reply.Allowed
}

// isApproved 检查给定作用域是否已被「始终允许」记忆覆盖。
func (a *Approver) isApproved(scopeKind, scope string) bool {
	switch scopeKind {
	case "dir":
		for _, ad := range a.approvedDirs {
			if underDir(scope, ad) {
				return true
			}
		}
	case "session":
		return a.approvedSess[scope]
	}
	return false
}

// remember 将当前作用域加入「始终允许」记忆。
func (a *Approver) remember(scopeKind, scope string) {
	switch scopeKind {
	case "dir":
		a.approvedDirs = append(a.approvedDirs, scope)
	case "session":
		a.approvedSess[scope] = true
	}
}

// underDir 判断 target 是否等于 base 或位于 base 之下。
func underDir(target, base string) bool {
	if target == base {
		return true
	}
	sep := string(filepath.Separator)
	if !strings.HasSuffix(base, sep) {
		base += sep
	}
	return strings.HasPrefix(target, base)
}

// PrintPrompt 打印审批提示（供终端兼容模式使用）。
// 在事件驱动模式下，TUI 自行渲染审批界面，不使用此方法。
func PrintPrompt(name, warning string) string {
	if warning != "" {
		return fmt.Sprintf("\n   %s %s\n   %s\n",
			redC("⚠️ 高危："), warning,
			yellowC("是否允许？[y]是 / [N]否 "))
	}
	return fmt.Sprintf("\n   %s\n", yellowC("▶ [y]本次 / [a]始终允许 / [N]否 "))
}

