func (m *Model) buildInput() {
	m.input = tview.NewTextArea().
		SetText("", false)
	m.input.SetBorder(true).SetTitle(" 输入（Ctrl+Enter 发送）").SetBorderColor(Theme.ChatBorder)

	m.input.SetInputCapture(func(event *tcell.EventKey) *tcell.EventKey {
		// Ctrl+Enter → 提交
		if event.Key() == tcell.KeyEnter && event.Modifiers()&tcell.ModCtrl != 0 {
			text := strings.TrimSpace(m.input.GetText())
			if text == "" {
				return nil
			}
			m.input.SetText("", false)

			// 记录历史
			m.inputHistory = append(m.inputHistory, text)
			if len(m.inputHistory) > 100 {
				m.inputHistory = m.inputHistory[len(m.inputHistory)-100:]
			}
			m.historyIdx = len(m.inputHistory)

			m.chatCh <- text
			return nil
		}
		switch event.Key() {
		case tcell.KeyUp:
			if len(m.inputHistory) > 0 && m.historyIdx > 0 {
				m.historyIdx--
				m.input.SetText(m.inputHistory[m.historyIdx], false)
			}
			return nil
		case tcell.KeyDown:
			if m.historyIdx < len(m.inputHistory)-1 {
				m.historyIdx++
				m.input.SetText(m.inputHistory[m.historyIdx], false)
			} else if m.historyIdx == len(m.inputHistory)-1 {
				m.historyIdx = len(m.inputHistory)
				m.input.SetText("", false)
			}
			return nil
		case tcell.KeyTab:
			m.sidebar.Toggle()
			m.adjustSidebarWidth()
			return nil
		case tcell.KeyCtrlW:
			m.sidebar.CycleMode()
			return nil
		}
		return event
	})
}

